func FrW() int32 {
	// cells of a row
	return 36
}

func FrNpred() int32 {
	return 10
}

func FrNumber(row int32) int32 {
	return FrRows[row*36+0]
}

func FrBlock(row int32) int32 {
	return FrRows[row*36+1]
}

func FrWinner(row int32) int32 {
	return FrRows[row*36+2]
}

func FrReason(row int32) int32 {
	return FrRows[row*36+3]
}

func FrFlags(row int32) int32 {
	return FrRows[row*36+4]
}

func FrConf(row int32) int32 {
	return FrRows[row*36+5]
}

func FrPcol(row int32, k int32) int32 {
	return FrRows[row*36+(6+(k*3))]
}

func FrPcmp(row int32, k int32) int32 {
	return FrRows[row*36+(7+(k*3))]
}

func FrPset(row int32, k int32) int32 {
	return FrRows[row*36+(8+(k*3))]
}

func FrDefence(row int32) int32 {
	// The defence of SPEC 9.5 a row of block 200 is (1-6, by the tens digit of its number minus 19; 24x is the seals', 5), 0 for every other row.
	if FrBlock(row) != 200 {
		return 0
	}
	return (FrNumber(row) / 10) - 19
}

func FrOrder(k int32) int32 {
	// The k-th block a word group is tried against (D224); -1 after the last.
	if k == 0 {
		return 400
	}
	if k == 1 {
		return 600
	}
	if k == 2 {
		return 200
	}
	if k == 3 {
		return 300
	}
	if k == 4 {
		return 100
	}
	return -1
}

func frHolds(row int32, gv *port.Cells) int32 {
	// 1 when every predicate of `row` holds on the group columns `gv`.
	var k int32 = 0
	var col int32 = 0
	var v int32 = 0
	var s int32 = 0
	var c int32 = 0
	for k < FrNpred() {
		col = FrPcol(row, k)
		if col >= 0 {
			v = port.CellsAt(gv, col)
			s = FrSetting(FrPset(row, k))
			c = FrPcmp(row, k)
			if (c == FcEq()) && (v != s) {
				return 0
			}
			if (c == FcNe()) && (v == s) {
				return 0
			}
			if (c == FcGe()) && ((v < 0) || (v < s)) {
				return 0
			}
			if (c == FcLt()) && ((v < 0) || (v >= s)) {
				return 0
			}
		}
		k += 1
	}
	return 1
}

func FrDecide(gv *port.Cells) int32 {
	// The row (an index of `fr-rows`) of the first rule that holds on the group columns `gv`, trying the blocks in `fr-order` and the
	// rows of a block in table order; -1 when none holds (the default row 190 holds for every group, so never in practice).
	var n int32 = 54
	var b int32 = 0
	var blk int32 = 0
	var r int32 = 0
	for FrOrder(b) >= 0 {
		blk = FrOrder(b)
		r = 0
		for r < n {
			if FrBlock(r) == blk {
				if frHolds(r, gv) == 1 {
					return r
				}
			}
			r += 1
		}
		b += 1
	}
	return -1
}

func FrDecideBlock(gv *port.Cells, blk int32) int32 {
	// The row (an index of `fr-rows`) of the first rule OF BLOCK `blk` that holds on the measures `gv`; -1 when none does. Block 500 reads the graphics
	// measures (`gmz`, codes 100 and up, in a vector of 128 cells), which have a default row (599) so that the answer is never -1 there.
	var n int32 = 54
	var r int32 = 0
	for r < n {
		if FrBlock(r) == blk {
			if frHolds(r, gv) == 1 {
				return r
			}
		}
		r += 1
	}
	return -1
}
